function findArray(pref) {
  const out = [];
  for (let i = 0; i < pref.length; i++) {
    // XOR of everything recovered so far, recomputed from scratch.
    let running = 0;
    for (let j = 0; j < i; j++) running ^= out[j];
    // Choose each bit of the next value so the running XOR gains exactly pref[i]'s bits.
    let value = 0;
    for (let bit = 0; bit < 21; bit++) {
      const have = Math.floor(running / 2 ** bit) % 2;
      const want = Math.floor(pref[i] / 2 ** bit) % 2;
      if (have !== want) value += 2 ** bit;
    }
    out.push(value);
  }
  return out;
}

